async (page) => {
  const ops = [];
  page.on('request', r => { if (r.url().includes('/graphql') && r.method()==='POST') { try { ops.push(r.postDataJSON()?.operationName); } catch {} } });
  const name = page.getByRole('textbox', { name: 'Name', exact: true });
  await name.fill('Monospace Zip Tee');
  const headerBefore = await page.getByTestId('page-header').innerText();
  const saveEnabled = await page.getByTestId('button-bar-confirm').isEnabled();
  const respP = page.waitForResponse(r => r.request().method()==='POST' && r.request().postDataJSON()?.operationName === 'ProductUpdate');
  await page.getByTestId('button-bar-confirm').click();
  const resp = await respP;
  const body = await resp.json();
  await page.getByText('Saved changes').waitFor().catch(()=>{});
  const notif = await page.getByRole('region', { name: /Notifications/ }).innerText();
  const headerAfter = await page.getByTestId('page-header').innerText();
  const saveAfter = await page.getByTestId('button-bar-confirm').isEnabled();
  return { headerBefore, saveEnabled, ops, body: JSON.stringify(body).slice(0,600), notif, headerAfter, saveAfter, title: await page.title() };
}

async (page) => {
  const { expect } = require('@playwright/test');
  const save = page.getByTestId('button-bar-confirm');
  let settledDisabled = null;
  try { await expect(save).toBeDisabled({ timeout: 5000 }); settledDisabled = true; } catch { settledDisabled = false; }
