1	import { e2eConfig } from "../../config.ts";
2	import { expect, test } from "../../fixtures/test.ts";
3	import { OrderPage } from "../../pages/orderPage.ts";
4	import { findOrderId, ORDERS_SCENARIO } from "../../scenarios/orders.ts";
5	
6	/**
7	 * What happens to an order after it is placed. Replaces legacy SALEOR_77 and 80 (paid,
8	 * fulfilled, tracked - one lifecycle), SALEOR_78 (partial manual captures) and SALEOR_81
9	 * and 82 (address edits either side of fulfillment). SALEOR_79, the same lifecycle on the
10	 * deprecated payment (`Payment` object) flow, is deliberately not ported.
11	 */
12	test.use({ scenario: ORDERS_SCENARIO });
13	
14	const config = e2eConfig();
15	
16	test("Mark as paid, fulfill and add tracking #e2e", async ({ page }) => {
17	  // Arrange
18	  const orderPage = new OrderPage(page);
19	
20	  await orderPage.goto(await findOrderId(config, "unpaid"));
21	
22	  // Act & Assert
23	  await test.step("mark as paid", async () => {
24	    await orderPage.markAsPaid("e2e-reference");
25	    await expect(orderPage.paymentStatusBadges).toContainText("Fully charged");
26	    await expect(orderPage.transactions).toContainText("Mark-as-paid transaction");
27	  });
28	
29	  await test.step("fulfill", async () => {
30	    await orderPage.fulfillAll();
31	    await expect(orderPage.statusInfo).toHaveText("Fulfilled");
32	  });
33	
34	  await test.step("add tracking", async () => {
35	    await orderPage.addTracking("TRACK-123");
36	    await expect(orderPage.trackingNumber).toContainText("TRACK-123");
37	  });
38	});
39	
40	test("Manual captures charge an order in parts #e2e", async ({ page }) => {
41	  // Arrange
42	  const orderPage = new OrderPage(page);
43	
44	  await orderPage.goto(await findOrderId(config, "unpaid"));
45	
46	  // Read rather than computed: the scenario's shipping method has a seeded, random price.
47	  const total = await orderPage.readTotal();
48	  const firstPart = 1;
49	
50	  // Act & Assert
51	  await test.step("a capture below the total leaves the order partly charged", async () => {
52	    await orderPage.captureManually({ description: "first part", amount: firstPart });
53	    await expect(orderPage.paymentStatusBadges).toContainText("Not fully charged");
54	    await expect(orderPage.statusInfo).toHaveText("Unfulfilled");
55	  });
56	
57	  await test.step("capturing the rest charges it fully", async () => {
58	    await orderPage.captureManually({ description: "second part", amount: total - firstPart });
59	    await expect(orderPage.paymentStatusBadges).toContainText("Fully charged");
60	    await expect(orderPage.transactions.getByText("Manual capture")).toHaveCount(2);
61	  });
62	});
63	
64	test("Addresses stay editable before and after fulfillment #e2e", async ({ page }) => {
