import { e2eConfig } from "../../config.ts";
import { expect, test } from "../../fixtures/test.ts";
import { adminToken, gql } from "../../lib/graphql.ts";
import { ORDERS_SCENARIO, PRODUCTS } from "../../scenarios/orders.ts";

/**
 * A staff member renames a product from its details page: they change the Name field,
 * save with the save bar, and the product carries the new name in the page header right
 * after saving and again after a full page reload.
 */
test.use({ scenario: ORDERS_SCENARIO });

const config = e2eConfig();

const NEW_NAME = "E2E Zip Hoodie";

type ProductUpdateResponse = {
  data: { productUpdate: { errors: unknown[] } };
};

/**
 * The id of the scenario product with the given SKU. A read, so it is safe at test time;
 * ids are not constants because every build of the dump mints new ones.
 */
const findProductId = async (sku: string): Promise<string> => {
  const data = await gql<{ productVariant: { product: { id: string } } | null }>(
    config,
    `query($sku: String!) { productVariant(sku: $sku) { product { id } } }`,
    { sku },
    await adminToken(config),
  );

  if (!data.productVariant) {
    throw new Error(`the "${ORDERS_SCENARIO}" scenario has no variant "${sku}"`);
  }

  return data.productVariant.product.id;
};

test.describe("Products - rename", () => {
  test("Staff can rename a product and the new name persists #e2e #products", async ({
    page,
  }) => {
    // Arrange
    const nameInput = page.getByRole("textbox", { name: "Name", exact: true });
    const pageHeader = page.getByTestId("page-header");
    const saveButton = page.getByTestId("button-bar-confirm");
    const productId = await findProductId(PRODUCTS.hoodie.sku);

    await page.goto(`/products/${productId}`);
    await expect(nameInput).toHaveValue(PRODUCTS.hoodie.name);
    await expect(pageHeader.getByTitle(PRODUCTS.hoodie.name, { exact: true })).toBeVisible();
    await expect(saveButton).toBeDisabled();

    // Act & Assert
    await test.step("rename and save", async () => {
      await nameInput.fill(NEW_NAME);
      await expect(nameInput).toHaveValue(NEW_NAME);
      await expect(saveButton).toBeEnabled();

      const productUpdate = page.waitForResponse(
        response =>
          response.request().method() === "POST" &&
          response.request().postDataJSON()?.operationName === "ProductUpdate",
      );

      await saveButton.click();

      const body: ProductUpdateResponse = await (await productUpdate).json();

      expect(body.data.productUpdate.errors).toEqual([]);
      await expect(page.getByText("Product updated")).toBeVisible();
      await expect(saveButton).toBeDisabled();
      // The header follows the refetched product, not the form, so it updates after save.
      await expect(pageHeader.getByTitle(NEW_NAME, { exact: true })).toBeVisible();
      await expect(pageHeader.getByTitle(PRODUCTS.hoodie.name, { exact: true })).toHaveCount(0);
    });

    await test.step("reload", async () => {
      await page.reload();
      // The field renders empty until the product loads, so wait on the value itself.
      await expect(nameInput).toHaveValue(NEW_NAME);
      await expect(pageHeader.getByTitle(NEW_NAME, { exact: true })).toBeVisible();
      await expect(page).toHaveTitle(`${NEW_NAME} | Saleor e-commerce`);
      await expect(saveButton).toBeDisabled();
    });
  });
});

