2	import { buttonMessages } from "@dashboard/intl";
3	import { Button, type ButtonProps, sprinkles } from "@saleor/macaw-ui-next";
4	import clsx from "clsx";
5	import { Check } from "lucide-react";
6	import { useEffect, useRef, useState } from "react";
7	import { defineMessages, useIntl } from "react-intl";
8	
9	import styles from "./ConfirmButton.module.css";
10	
11	const DEFAULT_NOTIFICATION_SHOW_TIME = 3000;
12	
13	const messages = defineMessages({
14	  tryAgain: {
15	    id: "Oy1LhB",
16	    defaultMessage: "Try again",
17	    description: "button error state label",
18	  },
19	});
20	
21	export type ConfirmButtonTransitionState = "default" | "loading" | "success" | "error";
22	
23	type ConfirmButtonLabels = Partial<Record<"confirm" | "error", string>>;
24	
25	export interface ConfirmButtonProps extends ButtonProps {
26	  labels?: ConfirmButtonLabels;
27	  noTransition?: boolean;
28	  transitionState: ConfirmButtonTransitionState;
29	  onTransitionToDefault?: () => void;
30	}
31	
32	// Here you can find original implementation
33	// https://github.com/saleor/macaw-ui/blob/canary/legacy/src/ConfirmButton/ConfirmButton.tsx
34	
35	export const ConfirmButton = ({
36	  labels,
37	  noTransition,
38	  transitionState,
39	  onTransitionToDefault,
40	  onClick,
41	  disabled,
42	  children,
43	  variant,
44	  className,
45	  ...props
46	}: ConfirmButtonProps) => {
47	  const intl = useIntl();
48	  const [displayCompletedActionState, setDisplayCompletedActionState] = useState(false);
49	  const timeout = useRef<number>();
50	  const isLoading = transitionState === "loading";
51	  const isCompleted = noTransition ? transitionState !== "default" : displayCompletedActionState;
52	  const isSaveDisabled = !isCompleted && !!disabled;
53	  const isSuccess = transitionState === "success" && isCompleted;
54	  const isError = transitionState === "error" && isCompleted;
55	  const isInteractionLocked = isLoading || isSuccess;
56	  const defaultLabels: ConfirmButtonLabels = {
57	    confirm: intl.formatMessage(buttonMessages.save),
58	    error: intl.formatMessage(messages.tryAgain),
59	  };
60	  const componentLabels: ConfirmButtonLabels = {
61	    ...defaultLabels,
62	    ...labels,
63	  };
64	
65	  useEffect(() => {
66	    if (!noTransition && transitionState === "loading") {
67	      setDisplayCompletedActionState(true);
68	    }
69	  }, [transitionState, noTransition]);
70	  useEffect(() => {
71	    if (noTransition) {
72	      return;
73	    }
74	
75	    if ((["error", "success"] as ConfirmButtonTransitionState[]).includes(transitionState)) {
76	      timeout.current = setTimeout(() => {
77	        setDisplayCompletedActionState(false);
78	
79	        if (onTransitionToDefault) {
80	          onTransitionToDefault();
81	        }
82	      }, DEFAULT_NOTIFICATION_SHOW_TIME) as unknown as number;
83	    } else if (transitionState === "loading") {
84	      clearTimeout(timeout.current);
85	    }
86	
87	    return () => {
88	      if (timeout.current) {
89	        clearTimeout(timeout.current);
90	      }
91	    };
92	  }, [noTransition, transitionState, onTransitionToDefault]);
93	
94	  const renderContent = () => {
95	    if (transitionState === "loading") {
96	      return (
97	        // TODO: Replace with new component when it will be ready https://github.com/saleor/macaw-ui/issues/443
98	        <SaleorThrobber size={20} data-test-id="button-progress" className={styles.indicator} />
99	      );
100	    }
101	
102	    if (transitionState === "success" && isCompleted) {
103	      return (
104	        // TODO: Replace with new component when it will be ready https://github.com/saleor/macaw-ui/issues/443
105	        <Check data-test-id="button-success" className={styles.indicator} />
106	      );
107	    }
108	
109	    return null;
110	  };
111	  const getByLabelText = () => {
112	    if (isError) {
113	      return componentLabels.error;
114	    }
115	
116	    return children || componentLabels.confirm;
117	  };
118	
119	  return (
120	    <Button
121	      {...props}
122	      className={clsx(
123	        styles.button,
124	        className,
125	        (isInteractionLocked || isSaveDisabled) && styles.noInteraction,
126	      )}
127	      variant={isError ? "error" : variant}
128	      disabled={isSaveDisabled}
129	      aria-busy={isLoading}
130	      tabIndex={isInteractionLocked ? -1 : undefined}
131	      onClick={isInteractionLocked ? undefined : onClick}
132	      data-test-state={isCompleted ? transitionState : "default"}
133	    >
134	      {renderContent()}
135	      <span

